3	namespace App\Http\Controllers\Api\Professional;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
7	use App\Http\Controllers\Concerns\ResolveCurrentSite;
8	use App\Models\Analytics\LinkClick;
9	use App\Services\Cache\CacheKeyGenerator;
10	use App\Services\Cache\CacheLockService;
11	use Illuminate\Http\JsonResponse;
12	use Illuminate\Http\Request;
13	use Illuminate\Support\Carbon;
14	use Illuminate\Support\Facades\Cache;
15	use Illuminate\Support\Facades\DB;
16	use Throwable;
17	
18	// NOTE: keep shopSummary in sync with summary()'s date-range parsing logic —
19	// both accept the same ?days / ?from / ?to / ?group_by query params.
20	
21	// V2: Site visit analytics (visits, clicks, devices, countries, traffic sources). Unrelated to commerce — site identity analytics only.
22	class ProfessionalAnalyticsController extends ApiController
23	{
24	    use ResolveCurrentProfessional;
25	    use ResolveCurrentSite;
26	
27	    public function __construct(private CacheLockService $cacheLock) {}
28	
29	    public function summary(Request $request): JsonResponse
30	    {
31	        $professional = $this->currentProfessional($request);
32	
33	        $days = (int) $request->query('days', 30);
34	        $days = max(1, min(365, $days));
35	        $groupBy = mb_strtolower(trim((string) $request->query('group_by', 'day')));
36	        $forceHourly = $groupBy === 'hour';
37	
38	        $fromParam = $request->query('from');
39	        $toParam = $request->query('to');
40	
41	        try {
42	            if ($forceHourly && ! $fromParam && ! $toParam) {
43	                $to = Carbon::now()->utc();
44	                $from = $to->copy()->subHours(24)->startOfHour();
45	            } elseif ($fromParam || $toParam) {
46	                $from = $fromParam
47	                    ? Carbon::parse($fromParam)->startOfDay()
48	                    : Carbon::now()->subDays($days)->startOfDay();
49	
50	                $to = $toParam
51	                    ? Carbon::parse($toParam)->endOfDay()
52	                    : Carbon::now()->endOfDay();
53	            } else {
54	                $to = Carbon::now()->endOfDay();
55	                $from = Carbon::now()->subDays($days)->startOfDay();
56	            }
57	        } catch (Throwable $e) {
58	            return $this->error(
59	                'Invalid date range.  Use YYYY-MM-DD for from/to.',
60	                422,
61	                [
62	                    'from' => $fromParam ? ['Invalid date.'] : [],
63	                    'to' => $toParam ? ['Invalid date.'] : [],
64	                ]
65	            );
66	        }
67	
68	        if ($from->gt($to)) {
69	            return $this->error('Invalid date range: from must be before to. ', 422);
70	        }
71	
72	        $site = $professional->site;
73	        if (! $site) {
74	            return $this->error('professional has no site.', 404);
75	        }
76	
77	        $professionalTimezone = trim((string) ($professional->timezone ?? '')) ?: 'UTC';
78	        $hourlyCutoff = now()->utc()->subHours(24);
79	        $useHourlyBuckets = $forceHourly || (
80	            $from->copy()->utc()->gte($hourlyCutoff)
81	            && $to->copy()->utc()->lte(now()->utc()->addMinute())
82	        );
83	
84	        // Version token lets invalidateAnalytics() bust ALL summary keys for this
85	        // professional at once, regardless of date-range or granularity suffix.
86	        $summaryVersion = (int) Cache::get(
87	            CacheKeyGenerator::analyticsSummaryVersion($professional->id),
88	            0
89	        );
90	
91	        $cacheKey = CacheKeyGenerator::analyticsSummary(
92	            $professional->id,
93	            $from->format('YmdH'),
94	            $to->format('YmdH')
95	        ).':'.($useHourlyBuckets ? 'hour' : 'day').":v{$summaryVersion}";
96	
97	        // Cache for 5 minutes (or longer for historical data)
98	        $cacheTTL = $to->isToday() ? now()->addMinutes(5) : now()->addHours(24);
99	
100	        $data = $this->cacheLock->rememberLocked($cacheKey, $cacheTTL, function () use ($professional, $from, $to, $site, $professionalTimezone, $useHourlyBuckets) {
101	            // All your existing query logic here
102	
103	            // Totals (visits)
104	            $visitsAgg = DB::table('analytics.site_visits')
105	                ->where('professional_id', $professional->id)
106	                ->whereBetween('occurred_at', [$from, $to])
107	                ->selectRaw('COUNT(*) as total_visits')
108	                ->selectRaw('COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as unique_visitors')
109	                ->selectRaw('MAX(occurred_at) as last_visit_at')
110	                ->first();
111	
112	            // Defaults ensure page-view analytics still works if click analytics queries fail.
113	            $clicksAgg = (object) [
114	                'total_clicks' => 0,
115	                'unique_clickers' => 0,
116	                'last_click_at' => null,
117	            ];
118	            $clicksByDay = collect();
119	            $topLinks = collect();
120	            $topSections = collect();
121	
122	            try {
123	                $clicksAgg = DB::table('analytics.link_clicks')
124	                    ->where('professional_id', $professional->id)
125	                    ->whereBetween('occurred_at', [$from, $to])
126	                    ->selectRaw('COUNT(*) as total_clicks')
127	                    ->selectRaw('COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as unique_clickers')
128	                    ->selectRaw('MAX(occurred_at) as last_click_at')
129	                    ->first();
130	            } catch (Throwable) {
131	                $clicksAgg = (object) [
132	                    'total_clicks' => 0,
133	                    'unique_clickers' => 0,
134	                    'last_click_at' => null,
135	                ];
136	            }
137	
138	            $totalVisits = (int) ($visitsAgg->total_visits ?? 0);
139	            $totalClicks = (int) ($clicksAgg->total_clicks ?? 0);
140	
141	            // Daily charts (unique visitors/clickers)
142	            if ($useHourlyBuckets) {
143	                $fromUtc = $from->copy()->utc();
144	                $toUtc = $to->copy()->utc();
145	
146	                $visitsByDay = DB::table('analytics.site_metrics_hourly as h')
147	                    ->where('h.professional_id', $professional->id)
148	                    ->whereBetween('h.hour_start', [$fromUtc, $toUtc])
149	                    ->selectRaw("DATE_TRUNC('hour', h.hour_start) as day")
150	                    ->selectRaw('COALESCE(SUM(h.unique_visitors), 0) as count')
151	                    ->groupByRaw("DATE_TRUNC('hour', h.hour_start)")
152	                    ->orderBy('day')
153	                    ->get();
154	
155	                $clicksByDay = DB::table('analytics.site_metrics_hourly as h')
156	                    ->where('h.professional_id', $professional->id)
157	                    ->whereBetween('h.hour_start', [$fromUtc, $toUtc])
158	                    ->selectRaw("DATE_TRUNC('hour', h.hour_start) as day")
159	                    ->selectRaw('COALESCE(SUM(h.unique_clickers), 0) as count')
160	                    ->groupByRaw("DATE_TRUNC('hour', h.hour_start)")
161	                    ->orderBy('day')
162	                    ->get();
163	            } else {
164	                $visitsByDay = DB::table('analytics.site_visits')
165	                    ->where('professional_id', $professional->id)
166	                    ->whereBetween('occurred_at', [$from, $to])
167	                    ->selectRaw('DATE(occurred_at) as day, COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as count')
168	                    ->groupByRaw('DATE(occurred_at)')
169	                    ->orderBy('day')
170	                    ->get();
171	
172	                try {
173	                    $clicksByDay = DB::table('analytics.link_clicks')
174	                        ->where('professional_id', $professional->id)
175	                        ->whereBetween('occurred_at', [$from, $to])
176	                        ->selectRaw('DATE(occurred_at) as day, COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as count')
177	                        ->groupByRaw('DATE(occurred_at)')
178	                        ->orderBy('day')
179	                        ->get();
180	                } catch (Throwable) {
181	                    $clicksByDay = collect();
182	                }
183	            }
184	
185	            // Device breakdown (unique visitors)
186	            $deviceCase = "
187	                CASE
188	                    WHEN device_type = 'desktop' THEN 'desktop'
189	                    WHEN device_type IN ('mobile','tablet') THEN 'mobile'
190	                    ELSE 'other'
191	                END
192	            ";
193	
194	            $deviceBreakdownRaw = DB::table('analytics.site_visits')
195	                ->where('professional_id', $professional->id)
196	                ->whereBetween('occurred_at', [$from, $to])
197	                ->selectRaw("$deviceCase as device, COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as visitors")
198	                ->groupByRaw($deviceCase)
199	                ->get()
200	                ->keyBy('device');
201	
202	            $devices = [
203	                'desktop' => (int) ($deviceBreakdownRaw->get('desktop')?->visitors ?? 0),
204	                'mobile' => (int) ($deviceBreakdownRaw->get('mobile')?->visitors ?? 0),
205	                'other' => (int) ($deviceBreakdownRaw->get('other')?->visitors ?? 0),
206	            ];
207	
208	            $visitsByDayByDevice = DB::table('analytics.site_visits')
209	                ->where('professional_id', $professional->id)
210	                ->whereBetween('occurred_at', [$from, $to])
211	                ->selectRaw("DATE(occurred_at) as day, $deviceCase as device, COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as count")
212	                ->groupByRaw("DATE(occurred_at), $deviceCase")
213	                ->orderBy('day')
214	                ->get();
215	
216	            // Countries (unique visitors)
217	            $countriesRaw = DB::table('analytics.site_visits')
218	                ->where('professional_id', $professional->id)
219	                ->whereBetween('occurred_at', [$from, $to])
220	                ->selectRaw("COALESCE(country_code, 'UN') as country_code, COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as visitors")
221	                ->groupByRaw("COALESCE(country_code, 'UN')")
222	                ->orderByDesc('visitors')
223	                ->get();
224	
225	            $topCountries = $countriesRaw->take(4)->values();
226	            $otherCount = (int) $countriesRaw->slice(4)->sum('visitors');
227	
228	            $countries = $topCountries->map(fn ($r) => [
229	                'country_code' => $r->country_code,
230	                'visitors' => (int) $r->visitors,
231	            ])->all();
232	
233	            if ($otherCount > 0) {
234	                $countries[] = ['country_code' => 'OTHER', 'visitors' => $otherCount];
235	            }
236	
237	            // Referrer/source breakdown (unique visitors)
238	            $sourceCase = "
239	                CASE
240	                    WHEN COALESCE(utm_source,'') ILIKE 'instagram%' OR COALESCE(referrer,'') ILIKE '%instagram.com%' OR COALESCE(referrer,'') ILIKE '%l.instagram.com%' THEN 'Instagram'
241	                    WHEN COALESCE(utm_source,'') ILIKE 'facebook%'  OR COALESCE(referrer,'') ILIKE '%facebook.com%'  OR COALESCE(referrer,'') ILIKE '%lm.facebook.com%'  OR COALESCE(referrer,'') ILIKE '%l.facebook.com%' THEN 'Facebook'
