243	                    WHEN COALESCE(utm_source,'') ILIKE 'youtube%'   OR COALESCE(referrer,'') ILIKE '%youtube.com%'   OR COALESCE(referrer,'') ILIKE '%youtu.be%' THEN 'YouTube'
244	                    WHEN COALESCE(utm_source,'') ILIKE 'twitter%'   OR COALESCE(utm_source,'') ILIKE 'x%'          OR COALESCE(referrer,'') ILIKE '%twitter.com%' OR COALESCE(referrer,'') ILIKE '%t.co%' OR COALESCE(referrer,'') ILIKE '%x.com%' THEN 'X (Twitter)'
245	                    WHEN COALESCE(utm_source,'') ILIKE 'linkedin%'  OR COALESCE(referrer,'') ILIKE '%linkedin.com%' THEN 'LinkedIn'
