247	                    WHEN COALESCE(utm_source,'') ILIKE 'pinterest%' OR COALESCE(referrer,'') ILIKE '%pinterest.%'  THEN 'Pinterest'
248	                    WHEN COALESCE(utm_source,'') ILIKE 'reddit%'    OR COALESCE(referrer,'') ILIKE '%reddit.com%'   THEN 'Reddit'
249	                    WHEN COALESCE(utm_source,'') ILIKE 'google%'    OR COALESCE(referrer,'') ILIKE '%google.%'      THEN 'Organic (Google)'
