453	    public function shopSummary(Request $request): JsonResponse
454	    {
455	        $professional = $this->currentProfessional($request);
456	
457	        $days = (int) $request->query('days', 30);
458	        $days = max(1, min(365, $days));
459	        $groupBy = mb_strtolower(trim((string) $request->query('group_by', 'day')));
460	        $forceHourly = $groupBy === 'hour';
461	
462	        $fromParam = $request->query('from');
463	        $toParam = $request->query('to');
464	
465	        try {
466	            if ($forceHourly && ! $fromParam && ! $toParam) {
467	                $to = Carbon::now()->utc();
468	                $from = $to->copy()->subHours(24)->startOfHour();
469	            } elseif ($fromParam || $toParam) {
470	                $from = $fromParam
471	                    ? Carbon::parse($fromParam)->startOfDay()
472	                    : Carbon::now()->subDays($days)->startOfDay();
473	                $to = $toParam
474	                    ? Carbon::parse($toParam)->endOfDay()
475	                    : Carbon::now()->endOfDay();
476	            } else {
477	                $to = Carbon::now()->endOfDay();
478	                $from = Carbon::now()->subDays($days)->startOfDay();
479	            }
480	        } catch (Throwable) {
481	            return $this->error('Invalid date range.', 422);
482	        }
483	
484	        if ($from->gt($to)) {
485	            return $this->error('Invalid date range: from must be before to.', 422);
486	        }
487	
488	        $site = $professional->site;
489	        if (! $site) {
490	            return $this->error('Professional has no site.', 404);
491	        }
492	
493	        $hourlyCutoff = now()->utc()->subHours(24);
494	        $useHourlyBuckets = $forceHourly || (
495	            $from->copy()->utc()->gte($hourlyCutoff)
496	            && $to->copy()->utc()->lte(now()->utc()->addMinute())
497	        );
498	
499	        $summaryVersion = (int) Cache::get(
500	            CacheKeyGenerator::analyticsSummaryVersion($professional->id),
501	            0
502	        );
503	
504	        $cacheKey = 'analytics:shop:'.$professional->id.':'.$from->format('YmdH').':'.$to->format('YmdH').':'
505	            .($useHourlyBuckets ? 'hour' : 'day').":v{$summaryVersion}";
506	
507	        $cacheTTL = $to->isToday() ? now()->addMinutes(5) : now()->addHours(24);
508	
509	        $data = $this->cacheLock->rememberLocked($cacheKey, $cacheTTL, function () use ($professional, $from, $to, $useHourlyBuckets) {
510	            // ── Funnel totals ────────────────────────────────────────────────
511	
512	            $visitors = (int) DB::table('analytics.site_visits')
513	                ->where('professional_id', $professional->id)
514	                ->whereBetween('occurred_at', [$from, $to])
515	                ->count();
516	
517	            // Shop opens: clicks on blocks with block_type = 'shop'
518	            $shopOpens = (int) LinkClick::runForBlockForeignKey(
519	                function (string $clickBlockColumn) use ($professional, $from, $to) {
520	                    return DB::table('analytics.link_clicks as lc')
521	                        ->join('site.blocks as b', 'b.id', '=', "lc.{$clickBlockColumn}")
522	                        ->where('lc.professional_id', $professional->id)
523	                        ->whereBetween('lc.occurred_at', [$from, $to])
524	                        ->whereRaw("LOWER(COALESCE(b.block_type, '')) = 'shop'")
525	                        ->count();
526	                },
527	                0
528	            );
529	
530	            $cartAdds = (int) DB::table('analytics.cart_events')
531	                ->where('professional_id', $professional->id)
532	                ->where('event_type', 'cart_add')
533	                ->whereBetween('occurred_at', [$from, $to])
534	                ->count();
535	
536	            $checkouts = (int) DB::table('analytics.cart_events')
537	                ->where('professional_id', $professional->id)
538	                ->where('event_type', 'checkout_start')
539	                ->whereBetween('occurred_at', [$from, $to])
540	                ->count();
541	
542	            // Orders = distinct Shopify orders attributed to this affiliate
543	            $ordersResult = DB::table('commerce.commission_ledger_entries')
