598	    /**
599	     * Aggregate commerce KPIs for a window — used for both the current
600	     * period and the equal-length prior period (vs-prior change badges).
601	     *
602	     * Revenue is back-derived from the ledger: amount_cents (commission)
603	     * divided by commission_rate (percent). NULLIF guards rate=0 rows that
604	     * would otherwise divide by zero.
605	     *
606	     * Quantity is summed out of the calculation_metadata JSON bag captured
607	     * by ProcessShopifyOrderWebhookJob — the only place line-item quantity
608	     * lives, since the ledger itself is rolled up to one accrual per line.
609	     *
610	     * @return array{orders:int, cart_adds:int, checkouts:int, commission_cents:int, revenue_cents:int, avg_order_cents:int, avg_order_qty:float}
611	     */
612	    private function commerceAggregates(string $professionalId, Carbon $from, Carbon $to): array
613	    {
614	        $cartAdds = (int) DB::table('analytics.cart_events')
615	            ->where('professional_id', $professionalId)
616	            ->where('event_type', 'cart_add')
617	            ->whereBetween('occurred_at', [$from, $to])
618	            ->count();
619	
620	        $checkouts = (int) DB::table('analytics.cart_events')
621	            ->where('professional_id', $professionalId)
622	            ->where('event_type', 'checkout_start')
623	            ->whereBetween('occurred_at', [$from, $to])
624	            ->count();
625	
626	        $orderAgg = DB::table('commerce.commission_ledger_entries')
627	            ->where('affiliate_professional_id', $professionalId)
628	            ->where('entry_type', 'accrual')
629	            ->whereNotNull('shopify_order_id')
630	            ->whereBetween('occurred_at', [$from, $to])
631	            ->selectRaw('
632	                COUNT(DISTINCT shopify_order_id) as orders,
633	                SUM(amount_cents) as commission_cents,
634	                SUM(amount_cents * 100.0 / NULLIF(commission_rate, 0)) as revenue_cents,
635	                SUM((calculation_metadata->>\'quantity\')::int) as total_qty
636	            ')
637	            ->first();
638	
639	        $orders = (int) ($orderAgg->orders ?? 0);
640	        $commissionCents = (int) round((float) ($orderAgg->commission_cents ?? 0));
641	        $revenueCents = (int) round((float) ($orderAgg->revenue_cents ?? 0));
642	        $totalQty = (int) ($orderAgg->total_qty ?? 0);
643	
644	        $avgOrderCents = $orders > 0 ? (int) round($revenueCents / $orders) : 0;
645	        $avgOrderQty = $orders > 0 ? round($totalQty / $orders, 2) : 0.0;
646	
647	        return [
648	            'orders' => $orders,
649	            'cart_adds' => $cartAdds,
650	            'checkouts' => $checkouts,
651	            'commission_cents' => $commissionCents,
652	            'revenue_cents' => $revenueCents,
653	            'avg_order_cents' => $avgOrderCents,
654	            'avg_order_qty' => $avgOrderQty,
655	        ];
656	    }
