658	    /**
659	     * Commerce timeseries for the area chart — orders / commission / revenue
660	     * grouped by hour or day depending on bucket choice.
661	     *
662	     * @return array{orders_by_day:\Illuminate\Support\Collection, commission_by_day:\Illuminate\Support\Collection, revenue_by_day:\Illuminate\Support\Collection}
663	     */
664	    private function commerceCharts(string $professionalId, Carbon $from, Carbon $to, bool $useHourlyBuckets): array
665	    {
666	        $bucket = $useHourlyBuckets ? "DATE_TRUNC('hour', occurred_at)" : 'DATE(occurred_at)';
667	
668	        $rows = DB::table('commerce.commission_ledger_entries')
669	            ->where('affiliate_professional_id', $professionalId)
670	            ->where('entry_type', 'accrual')
671	            ->whereNotNull('shopify_order_id')
672	            ->whereBetween('occurred_at', [$from, $to])
673	            ->selectRaw("
674	                {$bucket} as bucket,
675	                COUNT(DISTINCT shopify_order_id) as orders,
676	                SUM(amount_cents) as commission_cents,
677	                SUM(amount_cents * 100.0 / NULLIF(commission_rate, 0)) as revenue_cents
678	            ")
679	            ->groupByRaw($bucket)
680	            ->orderBy('bucket')
681	            ->get();
682	
683	        return [
684	            'orders_by_day' => $rows->map(fn ($r) => [
685	                'bucket' => $r->bucket,
686	                'orders' => (int) $r->orders,
687	            ])->values(),
688	            'commission_by_day' => $rows->map(fn ($r) => [
689	                'bucket' => $r->bucket,
690	                'commission_cents' => (int) round((float) $r->commission_cents),
691	            ])->values(),
692	            'revenue_by_day' => $rows->map(fn ($r) => [
693	                'bucket' => $r->bucket,
694	                'revenue_cents' => (int) round((float) $r->revenue_cents),
695	            ])->values(),
696	        ];
697	    }
