699	    /**
700	     * Top products by commission earned in the window.
701	     *
702	     * Reads product title from the calculation_metadata JSON bag (captured
703	     * by ProcessShopifyOrderWebhookJob since the line-item title is the only
704	     * source available without a Shopify Admin call). Older rows pre-dating
705	     * the title capture render with a "Product #{id}" fallback.
706	     */
707	    private function topProducts(string $professionalId, Carbon $from, Carbon $to): \Illuminate\Support\Collection
708	    {
709	        return DB::table('commerce.commission_ledger_entries')
710	            ->where('affiliate_professional_id', $professionalId)
711	            ->where('entry_type', 'accrual')
712	            ->whereNotNull('shopify_order_id')
713	            ->whereBetween('occurred_at', [$from, $to])
714	            ->whereRaw("calculation_metadata->>'product_id' IS NOT NULL")
715	            ->selectRaw("
716	                calculation_metadata->>'product_id' as product_id,
717	                MAX(calculation_metadata->>'product_title') as product_title,
718	                COUNT(DISTINCT shopify_order_id) as orders,
719	                SUM(amount_cents) as commission_cents,
720	                SUM(amount_cents * 100.0 / NULLIF(commission_rate, 0)) as revenue_cents
721	            ")
722	            ->groupByRaw("calculation_metadata->>'product_id'")
723	            ->orderByDesc('commission_cents')
724	            ->limit(8)
