1	<?php
2	
3	use App\Http\Controllers\Api\Professional\Analytics\AffiliateCommerceAnalyticsController;
4	use App\Models\Core\Professional\Professional;
5	use Illuminate\Http\Request;
6	use Illuminate\Support\Str;
7	use Illuminate\Validation\ValidationException;
8	
9	beforeEach(function () {
10	    $this->controller = app(AffiliateCommerceAnalyticsController::class);
11	    $this->professional = new Professional(['id' => (string) Str::uuid(), 'timezone' => 'UTC']);
12	    Cache::flush();
13	});
14	
15	it('throws ValidationException when from is provided without to', function () {
16	    $request = Request::create('/', 'GET', ['from' => '2026-04-01']);
17	    $request->attributes->set('professional', $this->professional);
18	
19	    expect(fn () => $this->controller->overview($request))
20	        ->toThrow(ValidationException::class);
21	});
22	
23	it('throws ValidationException when to is provided without from', function () {
24	    $request = Request::create('/', 'GET', ['to' => '2026-04-19']);
25	    $request->attributes->set('professional', $this->professional);
26	
27	    expect(fn () => $this->controller->overview($request))
28	        ->toThrow(ValidationException::class);
29	});
30	
31	it('throws ValidationException when from is after to', function () {
32	    $request = Request::create('/', 'GET', ['from' => '2026-04-19', 'to' => '2026-04-01']);
33	    $request->attributes->set('professional', $this->professional);
34	
35	    expect(fn () => $this->controller->overview($request))
36	        ->toThrow(ValidationException::class);
37	});
38	
39	it('throws ValidationException for invalid date format', function () {
40	    $request = Request::create('/', 'GET', ['from' => '19-04-2026', 'to' => '20-04-2026']);
41	    $request->attributes->set('professional', $this->professional);
42	
43	    expect(fn () => $this->controller->overview($request))
44	        ->toThrow(ValidationException::class);
45	});
46	
47	it('returns zero totals and empty timeseries when no data exists', function () {
48	
49	    $queryMock = Mockery::mock(\Illuminate\Database\Query\Builder::class);
50	    $queryMock->shouldReceive('where')->andReturnSelf();
51	    $queryMock->shouldReceive('whereBetween')->andReturnSelf();
52	    $queryMock->shouldReceive('get')->andReturn(collect());
53	
54	    DB::shouldReceive('table')
55	        ->with('analytics.professional_metrics_daily')
56	        ->once()
57	        ->andReturn($queryMock);
58	
59	    $request = Request::create('/', 'GET', ['from' => '2026-04-01', 'to' => '2026-04-19']);
60	    $request->attributes->set('professional', $this->professional);
61	
62	    $response = $this->controller->overview($request);
63	    $data = json_decode($response->getContent(), true);
64	
65	    expect($data['range'])->toBe(['from' => '2026-04-01', 'to' => '2026-04-19'])
66	        ->and($data['totals']['orders_count'])->toBe(0)
67	        ->and($data['totals']['gross_cents'])->toBe(0)
68	        ->and($data['totals']['commission_accrued_cents'])->toBe(0)
69	        ->and($data['timeseries'])->toBe([]);
70	});
71	
72	it('defaults to last 30 days when no range params are given', function () {
73	
74	    $queryMock = Mockery::mock(\Illuminate\Database\Query\Builder::class);
75	    $queryMock->shouldReceive('where')->andReturnSelf();
76	    $queryMock->shouldReceive('whereBetween')->andReturnSelf();
77	    $queryMock->shouldReceive('get')->andReturn(collect());
78	
79	    DB::shouldReceive('table')
80	        ->with('analytics.professional_metrics_daily')
81	        ->andReturn($queryMock);
82	
83	    $request = Request::create('/', 'GET');
84	    $request->attributes->set('professional', $this->professional);
85	
86	    $response = $this->controller->overview($request);
87	    $data = json_decode($response->getContent(), true);
88	
89	    expect($data['range']['from'])->toBe(now()->subDays(29)->toDateString())
90	        ->and($data['range']['to'])->toBe(now()->toDateString());
91	});
92	
93	it('returns timeseries from daily rows', function () {
94	
95	    $queryMock = Mockery::mock(\Illuminate\Database\Query\Builder::class);
96	    $queryMock->shouldReceive('where')->andReturnSelf();
97	    $queryMock->shouldReceive('whereBetween')->andReturnSelf();
98	    $queryMock->shouldReceive('get')->andReturn(collect([
99	        (object) [
100	            'day' => '2026-04-18',
101	            'currency_code' => 'AUD',
102	            'orders_count' => 3,
103	            'gross_cents' => 12000,
104	            'refunded_cents' => 0,
105	            'net_cents' => 12000,
106	            'commission_accrued_cents' => 1200,
107	            'commission_reversed_cents' => 0,
108	            'commission_paid_cents' => 0,
109	        ],
110	        (object) [
111	            'day' => '2026-04-19',
112	            'currency_code' => 'AUD',
113	            'orders_count' => 1,
114	            'gross_cents' => 5000,
115	            'refunded_cents' => 0,
116	            'net_cents' => 5000,
117	            'commission_accrued_cents' => 500,
118	            'commission_reversed_cents' => 0,
119	            'commission_paid_cents' => 0,
120	        ],
121	    ]));
122	
123	    DB::shouldReceive('table')
124	        ->with('analytics.professional_metrics_daily')
125	        ->andReturn($queryMock);
126	
127	    $request = Request::create('/', 'GET', ['from' => '2026-04-18', 'to' => '2026-04-19']);
128	    $request->attributes->set('professional', $this->professional);
129	
130	    $response = $this->controller->overview($request);
131	    $data = json_decode($response->getContent(), true);
132	
133	    expect($data['totals']['orders_count'])->toBe(4)
134	        ->and($data['totals']['gross_cents'])->toBe(17000)
135	        ->and($data['totals']['currency_code'])->toBe('AUD')
136	        ->and($data['timeseries'])->toHaveCount(2)
137	        ->and($data['timeseries'][0]['bucket'])->toBe('2026-04-18')
138	        ->and($data['timeseries'][0]['orders_count'])->toBe(3);
139	});
